  <main class="app-shell">
    <section class="hero" aria-labelledby="page-title">
      <div class="eyebrow"><span class="eyebrow-dot"></span> Personal scheduling</div>
      <h1 id="page-title">Make time for what matters.</h1>
      <p class="hero-copy">Create a simple appointment in seconds. Your bookings stay private in this browser session.</p>
      <div class="hero-note"><span class="note-icon">✦</span><span>No account needed · No data leaves this page</span></div>
    </section>

    <section class="content-grid">
      <div class="form-card card">
        <div class="card-heading">
          <div>
            <p class="section-kicker">New appointment</p>
            <h2>Book a time</h2>
          </div>
          <div class="calendar-mark" aria-hidden="true">▦</div>
        </div>
        <form id="booking-form" novalidate>
          <div class="field-group">
            <label for="booking-name">Customer name <span>*</span></label>
            <input id="booking-name" data-testid="booking-name" name="name" type="text" placeholder="e.g. Alex Morgan" autocomplete="name" required>
          </div>
          <div class="field-group">
            <label for="booking-email">Email address <span>*</span></label>
            <input id="booking-email" data-testid="booking-email" name="email" type="email" placeholder="alex@example.com" autocomplete="email" required>
          </div>
          <div class="form-row">
            <div class="field-group">
              <label for="booking-date">Date <span>*</span></label>
              <input id="booking-date" data-testid="booking-date" name="date" type="date" required>
            </div>
            <div class="field-group">
              <label for="booking-time">Time <span>*</span></label>
              <input id="booking-time" data-testid="booking-time" name="time" type="time" required>
            </div>
          </div>
          <div class="field-group">
            <label for="booking-type">Appointment type <span>*</span></label>
            <select id="booking-type" data-testid="booking-type" name="type" required>
              <option value="" selected disabled>Select an appointment type</option>
              <option value="Consultation">Consultation</option>
              <option value="Follow-up">Follow-up</option>
              <option value="Project review">Project review</option>
              <option value="Discovery call">Discovery call</option>
            </select>
          </div>
          <button class="primary-button" id="booking-submit" data-testid="booking-submit" type="submit"><span>Confirm appointment</span><span class="button-arrow">→</span></button>
