document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('booking-form');
  const dateInput = document.getElementById('booking-date');
  const list = document.getElementById('booking-list');
  const emptyState = document.getElementById('empty-state');
  const confirmation = document.getElementById('booking-confirmation');
  const count = document.getElementById('booking-count');
  let bookings = [];

  const today = new Date();
  const pad = value => String(value).padStart(2, '0');
  dateInput.min = today.getFullYear() + '-' + pad(today.getMonth() + 1) + '-' + pad(today.getDate());

  function formatDate(value) {
    const parts = value.split('-');
    const date = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
    return date.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
  }

  function render() {
    list.querySelectorAll('[data-testid="booking"]').forEach(item => item.remove());
    emptyState.hidden = bookings.length !== 0;
    count.textContent = bookings.filter(item => !item.cancelled).length;
    bookings.forEach(booking => {
      const item = document.createElement('article');
      item.className = 'booking-item' + (booking.cancelled ? ' cancelled' : '');
      item.dataset.testid = 'booking';
      item.dataset.status = booking.cancelled ? 'cancelled' : 'active';
      const details = document.createElement('div');
      const top = document.createElement('div');
      top.className = 'booking-top';
      const name = document.createElement('h3');
      name.dataset.testid = 'booking-name-display';
      name.textContent = booking.name;
      const status = document.createElement('span');
      status.className = 'status';
      status.textContent = booking.cancelled ? 'Cancelled' : 'Confirmed';
      top.append(name, status);
      const meta = document.createElement('div');
      meta.className = 'booking-meta';
      meta.innerHTML = '<span class="booking-type"></span><br><span class="date-line"></span>';
      meta.querySelector('.booking-type').textContent = booking.type;
      meta.querySelector('.date-line').textContent = formatDate(booking.date) + ' · ' + booking.time;
      details.append(top, meta);
      const cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.className = 'cancel-button';
      cancel.dataset.testid = 'booking-cancel';
      cancel.textContent = 'Cancel';
      cancel.addEventListener('click', function () { booking.cancelled = true; render(); });
      item.append(details, cancel);
      list.appendChild(item);
    });
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    if (!form.checkValidity()) { form.reportValidity(); return; }
    const data = new FormData(form);
    const selectedDate = new Date(data.get('date') + 'T00:00:00');
    const nowDate = new Date(); nowDate.setHours(0, 0, 0, 0);
    if (selectedDate < nowDate) { dateInput.setCustomValidity('Please choose today or a future date.'); dateInput.reportValidity(); dateInput.setCustomValidity(''); return; }
    bookings.push({ name: data.get('name').trim(), email: data.get('email'), date: data.get('date'), time: data.get('time'), type: data.get('type'), cancelled: false });
    render();
    confirmation.textContent = 'Appointment confirmed — ' + bookings[bookings.length - 1].name + ' has been added to your schedule.';
    confirmation.hidden = false;
    form.reset();
    dateInput.min = today.getFullYear() + '-' + pad(today.getMonth() + 1) + '-' + pad(today.getDate());
  });
});

